+		case a.timestamp > b.timestamp:
+			return 1
+		case a.treeIndex < b.treeIndex:
+			return -1
+		case a.treeIndex > b.treeIndex:
+			return 1
+		default:
+			return strings.Compare(a.entryName, b.entryName)
+		}
+	})
+
+	result := make([]string, 0, len(ordered))
+	for _, item := range ordered {
+		result = append(result, item.value)
+	}
